Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAX_LIMIT = 1000009;
const int MOD_VALUE = 1000000007;

long long modExponentiation(long long base, long long exponent, long long mod) {
    long long res = 1, b = base;
    while (exponent > 0) {
        if (exponent & 1) res = (res * b) % mod;
        b = (b * b) % mod;
        exponent >>= 1;
    }
    return res;
}

int visitedStates[MAX_LIMIT];

int main() {
#ifndef ONLINE_JUDGE
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    int p, k;
    cin >> p >> k;
    int totalAnswer = 1;
    if (k == 0) {
        for (int i = 1; i < p; ++i)
            totalAnswer = (long long)totalAnswer * p % MOD_VALUE;
        cout << totalAnswer << endl;
        return 0;
    }
    for (int i = 0; i < p; ++i) {
        if (visitedStates[i]) continue;
        int j = i, d = 0;
        do {
            visitedStates[j] = ++d;
            j = (long long)j * k % p;
        } while (!visitedStates[j]);
        if (modExponentiation(k, d, p) == 1)
            totalAnswer = (long long)totalAnswer * p % MOD_VALUE;
    }
    cout << totalAnswer << endl;
#ifndef ONLINE_JUDGE
    fclose(stdin); fclose(stdout);
#endif
    return 0;
}
</original_code>
